1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"strings"
8		"time"
9	)
10	
11	// graphTaskContext is the response of `entire graph context`, the graph
12	// plugin's delegation surface for task context (COR-2217). The graph owns the
13	// queryable store; the brief calls this instead of maintaining its own copy of
14	// the snapshot. Field names mirror the provider's contextResponse contract.
15	type graphTaskContext struct {
16		SchemaVersion string                 `json:"schema_version"`
17		Commit        string                 `json:"commit"`
18		Tree          string                 `json:"tree"`
19		Symbols       []graphContextSymbol   `json:"symbols"`
20		Relations     []graphContextRelation `json:"relations"`
21		Tests         []graphContextSymbol   `json:"tests"`
22		LatencyMS     int64                  `json:"latency_ms"`
23		// StoreUnavailable means the provider ran but has no store for the
24		// committed tree. The brief degrades to its internal semantic path (or a
25		// warning), exactly as it would with the plugin absent.
26		StoreUnavailable bool   `json:"store_unavailable"`
27		Detail           string `json:"detail"`
28	}
29	
30	type graphContextSymbol struct {
31		ID            string  `json:"id"`
32		Name          string  `json:"name"`
33		QualifiedName string  `json:"qualified_name"`
34		Kind          string  `json:"kind"`
35		FilePath      string  `json:"file_path"`
36		StartLine     int     `json:"start_line"`
37		EndLine       int     `json:"end_line"`
38		Signature     string  `json:"signature"`
39		Language      string  `json:"language"`
40		Score         float64 `json:"score"`
41	}
42	
43	type graphContextRelation struct {
44		FromID     string  `json:"from_id"`
45		ToID       string  `json:"to_id"`
46		Type       string  `json:"type"`
47		Confidence float64 `json:"confidence"`
48	}
49	
50	// graphTaskContextTimeout bounds the delegation subprocess. The command
51	// answers from an indexed store in well under a second; the margin covers a
52	// cold binary start and a loaded machine, not a build.
53	const graphTaskContextTimeout = 15 * time.Second
54	
55	// fetchGraphTaskContext asks the graph plugin for task context. Any error —
56	// binary missing, a plugin version without the `context` verb, malformed
57	// output — reads as "delegation unavailable" and the caller falls back; it is
58	// never surfaced as a brief failure.
59	func fetchGraphTaskContext(ctx context.Context, runner CommandRunner, repoDir, graphBinary, task string, limit, testsLimit int) (graphTaskContext, error) {
60		if runner == nil {
61			return graphTaskContext{}, fmt.Errorf("graph context requires a command runner")
62		}
63		binary := strings.TrimSpace(graphBinary)
64		if binary == "" {
65			binary = "entire"
66		}
67		runCtx, cancel := context.WithTimeout(ctx, graphTaskContextTimeout)
68		defer cancel()
69		args := []string{"graph", "context", "--repo", repoDir, "--task", task, "--limit", fmt.Sprint(limit), "--tests-limit", fmt.Sprint(testsLimit)}
70		ignores, err := semanticProviderIgnoreFiles(repoDir)
71		if err != nil {
72			return graphTaskContext{}, err
73		}
74		for _, ignore := range ignores {
75			args = append(args, "--ignore-file", ignore)
76		}
77		stdout, stderr, err := runner.Run(runCtx, repoDir, binary, args...)
78	
79		if err != nil {
80			detail := strings.TrimSpace(string(stderr))
81			if detail == "" {
82				detail = strings.TrimSpace(string(stdout))
83			}
84			if detail != "" {
85				return graphTaskContext{}, fmt.Errorf("graph context: %w: %s", err, firstLine(detail))
86			}
87			return graphTaskContext{}, fmt.Errorf("graph context: %w", err)
88		}
89		var response graphTaskContext
90		if err := json.Unmarshal(stdout, &response); err != nil {
91			return graphTaskContext{}, fmt.Errorf("graph context returned unparseable output: %w", err)
92		}
93		return response, nil
94	}
95	
96	func firstLine(s string) string {
97		if index := strings.IndexByte(s, '\n'); index >= 0 {
98			return s[:index]
99		}
100		return s
101	}
102	
103	// graphContextSymbolRecords projects provider symbols into the brief's
104	// semanticRecord shape so every downstream consumer (departed-file filtering,
105	// caps, likely-file synthesis, rendering) works unchanged.
106	func graphContextSymbolRecords(symbols []graphContextSymbol) []semanticRecord {
107		records := make([]semanticRecord, 0, len(symbols))
108		for _, symbol := range symbols {
109			records = append(records, semanticRecord{
110				RecordType:    "symbol",
111				ID:            symbol.ID,
112				Kind:          symbol.Kind,
113				Name:          symbol.Name,
114				QualifiedName: symbol.QualifiedName,
115				FilePath:      symbol.FilePath,
116				StartLine:     symbol.StartLine,
117				EndLine:       symbol.EndLine,
118				Signature:     symbol.Signature,
119				Language:      symbol.Language,
120			})
121		}
122		return records
