312		}
313		timeout := indexOpts.timeout
314		if timeout <= 0 {
315			timeout = semanticSnapshotTimeout
316		}
317		ctx, cancel := context.WithTimeout(ctx, timeout)
318		defer cancel()
319		indexOpts.reportPhase("building Graph-owned store")
320		stdout, stderr, err := runner.RunWithEnv(ctx, repoDir, map[string]string{"ENTIRE_GRAPH_SEARCH_STORE": "1"}, binary, args...)
321		if err != nil {
322			return fmt.Errorf("Graph index: %w: %s", err, firstLine(strings.TrimSpace(string(stderr))))
323		}
324		d, err := fetchGraphStore(ctx, opts, repoDir, binary, profile)
325		if err != nil {
326			return err
327		}
328		unlock, err := acquireSemanticIndexLock(storage.BrainDir)
329		if err != nil {
330			return err
331		}
332		defer unlock()
333		// Preserve authored traces before removing any legacy graph artifacts.
334		if err = migrateLegacyGraphTraces(storage.BrainDir); err != nil {
335			return err
336		}
337		source := graphStoreSource(d, storage.BrainDir)
338		source.StorePath = ""
339		source.GeneratedAt = opts.Now().UTC()
340		source.Profile = profile
341		source.GraphRepoRoot = repoDir
342		if err = writeBrainSemanticSource(storage.BrainDir, storage.Key, source); err != nil {
343			return err
344		}
345		removed, err := removeLegacyGraphArtifacts(storage.BrainDir)
346		if err != nil {
347			return err
348		}
349		if removed {
350			fmt.Fprintln(os.Stderr, "brain: retired the duplicate semantic index; Graph owns code indexing now")
351		}
352	
353		var indexed struct {
354			CacheHit bool `json:"index_cache_hit"`
355		}
356		_ = json.Unmarshal(stdout, &indexed)
357		label := "Graph-owned index"
358		if indexed.CacheHit {
359			label += " already current"
360		}
361		fmt.Fprintf(cmd.OutOrStdout(), "%s: %d files, %d symbols, %d relations\n", label, d.Files, d.Symbols, d.Relations)
362		return nil
363	}
364	
365	// removeLegacyGraphArtifacts deletes the pre-Graph-ownership semantic store
366	// directories, if present, and reports whether it actually deleted anything --
367	// the one signal callers need to announce a real, one-time destructive
368	// removal rather than a routine no-op on an already-migrated brain.
369	func removeLegacyGraphArtifacts(brainDir string) (bool, error) {
370		removed := false
371		for _, rel := range []string{"semantic/generations", "semantic/snapshots"} {
372			if err := rejectExistingSymlinkPathComponents(brainDir, rel); err != nil {
373				return removed, err
374			}
375			path := filepath.Join(brainDir, rel)
376			if _, err := os.Lstat(path); err == nil {
377				removed = true
378			} else if !os.IsNotExist(err) {
379				return removed, err
380			}
381			if err := os.RemoveAll(path); err != nil {
382				return removed, err
383			}
384		}
385		return removed, nil
386	}
387	
388	func migrateBrainGraphStorage(brainDir, repoKey string) error {
389		unlock, err := acquireSemanticIndexLock(brainDir)
390		if err != nil {
391			return err
392		}
393		defer unlock()
394		manifest, err := loadBrainManifest(brainDir)
